        Self::new()
    }
}

impl Ppu {
    /// DMG 开机状态（Pan Docs Power_Up_Sequence 的硬件寄存器表，DMG 列），前缓冲为全白。
    pub fn new() -> Self {
        let mut regs = [0u8; 12];
        regs[0x0] = 0x91; // LCDC
        regs[0x1] = 0x85; // STAT
        regs[0x7] = 0xFC; // BGP
        Self {
            vram: [0; 0x2000],
            oam: [0; 0xA0],
            front: Box::new([0xFF; FRAME_PIXELS]),
            back: Box::new([0xFF; FRAME_PIXELS]),
            regs,
        }
    }

