    pub fn read_oam(&self, addr: u16) -> u8 {
        self.oam[(addr as usize - 0xFE00) % 0xA0]
    }

    /// CPU 写 OAM，`addr` 为绝对地址 0xFE00..=0xFE9F。
    pub fn write_oam(&mut self, addr: u16, v: u8) {
        self.oam[(addr as usize - 0xFE00) % 0xA0] = v;
