        match addr {
            0xFF40..=0xFF4B => self.regs[(addr - 0xFF40) as usize],
            _ => 0xFF,
        }
    }

    fn write_reg(&mut self, addr: u16, v: u8) {
        if let 0xFF40..=0xFF4B = addr {
            self.regs[(addr - 0xFF40) as usize] = v;
        }
    }
}

