180	/// 校验存档文件头：magic、版本、ROM 指纹。不足 magic 长度或 magic 不符都视为 `BadMagic`。
181	fn check_header(r: &mut StateReader, fingerprint: &[u8; FINGERPRINT_LEN]) -> Result<(), StateError> {
182	    let mut magic = [0u8; 7];
183	    r.bytes_into(&mut magic).map_err(|_| StateError::BadMagic)?;
184	    if &magic != STATE_MAGIC {
185	        return Err(StateError::BadMagic);
186	    }
187	    let version = r.u16()?;
188	    if version != STATE_VERSION {
189	        return Err(StateError::BadVersion(version));
190	    }
191	    let mut fp = [0u8; FINGERPRINT_LEN];
192	    r.bytes_into(&mut fp)?;
193	    if &fp != fingerprint {
194	        return Err(StateError::RomMismatch);
195	    }
196	    Ok(())
197	}

