39	/// 波形 RAM（FF30–FF3F）开机内容不确定，取 0x00。
40	fn apu_power_up() -> [u8; APU_LEN] {
41	    let mut apu = [0xFF; APU_LEN];
42	    let table: [(u16, u8); 21] = [
43	        (0xFF10, 0x80), // NR10
44	        (0xFF11, 0xBF), // NR11
45	        (0xFF12, 0xF3), // NR12
46	        (0xFF13, 0xFF), // NR13
47	        (0xFF14, 0xBF), // NR14
48	        (0xFF16, 0x3F), // NR21
49	        (0xFF17, 0x00), // NR22
50	        (0xFF18, 0xFF), // NR23
51	        (0xFF19, 0xBF), // NR24
52	        (0xFF1A, 0x7F), // NR30
53	        (0xFF1B, 0xFF), // NR31
54	        (0xFF1C, 0x9F), // NR32
55	        (0xFF1D, 0xFF), // NR33
56	        (0xFF1E, 0xBF), // NR34
57	        (0xFF20, 0xFF), // NR41
58	        (0xFF21, 0x00), // NR42
59	        (0xFF22, 0x00), // NR43
60	        (0xFF23, 0xBF), // NR44
61	        (0xFF24, 0x77), // NR50
62	        (0xFF25, 0xF3), // NR51
63	        (0xFF26, 0xF1), // NR52
64	    ];
65	    for (addr, v) in table {
66	        apu[(addr - 0xFF10) as usize] = v;
67	    }
68	    for b in &mut apu[0x20..] {
69	        *b = 0x00;
70	    }
71	    apu
72	}
