74	    /// 执行 1 条指令，或 1 次中断分派，或 HALT/锁死状态下的 1 个 M-cycle。
75	    /// 每次调用至少消耗 1 个 M-cycle（至少调用一次 read/write/idle），绝不为 0。
76	    pub fn step<B: CpuBus>(&mut self, bus: &mut B) {
77	        if self.locked {
78	            bus.idle();
79	            return;
80	        }
81	        if self.halted {
82	            if bus.pending() == 0 {
83	                // 外设由 bus 在这个 M-cycle 里照常推进。
84	                bus.idle();
85	                return;
86	            }
87	            // 有挂起中断即唤醒，不额外耗时（Mooneye halt_ime0/1 timing：与一串 NOP 等待的时序相同）。
88	            self.halted = false;
89	        }
90	        if self.ime && bus.pending() != 0 {
91	            self.dispatch(bus);
92	            return;
93	        }
94	        let enable_ime = self.ei_pending;
95	        self.ei_pending = false;
96	        let op = self.fetch_opcode(bus);
97	        self.execute(bus, op);
98	        if enable_ime && op != OP_DI {
99	            self.ime = true;
100	        }
101	    }
