1	//! OAM DMA 状态机（core 通道，D022；Pan Docs `OAM_DMA_Transfer.md`）。实际搬运由 Bus 驱动（PLAN §3.2）：
2	//! Bus 每个 M-cycle 先推进外设、再调用一次 `tick_mcycle`，返回 `Some((src, index))` 时从总线读 `src`
3	//! （不推进时钟、无副作用），再调用 `Ppu::dma_write_oam(index, v)`；之后才执行 CPU 这个 M-cycle 的访问。
4	//!
5	//! 冻结部分（D001）：下列公开方法的签名。
6	//!
7	//! 时序（M-cycle W 是 CPU 写 FF46 的那个周期）：
8	//! - W+1：启动延迟，不搬运；若此前有传输在进行，它在这个周期照常再搬 1 字节；
9	//! - W+2 … W+161：共 160 个 M-cycle，每个周期搬 1 字节，源 `XX00+i` → OAM 第 i 字节；
10	//! - `oam_blocked()` 恰好在搬运字节的那些 M-cycle 为真（CPU 在同一周期的 OAM 访问读到 0xFF、写入被忽略）。
11	//!
12	//! 这与 Pan Docs 的说明一致：传输占 160 个 M-cycle，"starts right after instruction"；
13	//! 紧凑例程（`ldh [c],a` 之后 159 个 M-cycle 的等待循环）末尾用 `ret z` 而不是 `ret`，
14	//! 正是为了让第一次读栈落在 W+162，避开 DMA 的最后一个 M-cycle W+161。
15	//! 传输进行中再写 FF46：按同样的启动延迟重新开始（从第 0 字节、新的源页）。
16	
17	use crate::state::{Snapshot, StateError, StateReader, StateWriter};
18	
19	/// 一次传输的字节数（OAM 大小）。
20	pub const DMA_LEN: u8 = 160;
21	
22	#[derive(Debug, Clone, PartialEq, Eq)]
23	pub struct Dma {
24	    /// 最近一次写入 FF46 的值（读 FF46 返回它）。
25	    reg: u8,
26	    /// 进行中的传输：源页（源地址高字节）。
27	    page: u8,
28	    /// 进行中的传输：下一个要搬的字节序号；`DMA_LEN` 表示没有进行中的传输。
29	    index: u8,
30	    /// 写 FF46 之后、启动延迟结束之前的新传输源页。
31	    pending: Option<u8>,
32	    /// 最近一个 M-cycle 是否搬运了字节（= CPU 在该周期内对 OAM 的访问被封锁）。
33	    transferring: bool,
34	}
35	
36	impl Default for Dma {
37	    fn default() -> Self {
38	        Self::new()
39	    }
40	}
41	
42	impl Dma {
43	    /// 开机状态：FF46 读 0xFF（Power_Up_Sequence 的 DMG 列），没有进行中的传输。
44	    pub fn new() -> Self {
45	        Self { reg: 0xFF, page: 0, index: DMA_LEN, pending: None, transferring: false }
46	    }
47	
48	    /// 读 FF46：最近一次写入的值。
49	    pub fn read_reg(&self) -> u8 {
50	        self.reg
51	    }
52	
53	    /// 写 FF46：经过 1 个 M-cycle 的启动延迟后开始（或重新开始）一次 160 字节的传输，源地址为 `v << 8`。
54	    pub fn write_reg(&mut self, v: u8) {
55	        self.reg = v;
56	        self.pending = Some(v);
57	    }
58	
59	    /// 推进 1 个 M-cycle；本周期需要搬运一个字节时返回 `Some((源地址, OAM 序号 0..160))`。
60	    pub fn tick_mcycle(&mut self) -> Option<(u16, u8)> {
61	        let out = if self.index < DMA_LEN {
62	            let i = self.index;
63	            self.index += 1;
64	            Some((u16::from(self.page) << 8 | u16::from(i), i))
65	        } else {
66	            None
67	        };
68	        // 启动延迟在这个周期结束：从下一个 M-cycle 起搬新传输的第 0 字节（覆盖进行中的旧传输）。
69	        if let Some(page) = self.pending.take() {
70	            self.page = page;
71	            self.index = 0;
72	        }
73	        self.transferring = out.is_some();
74	        out
75	    }
76	
77	    /// 最近一个 M-cycle 是否在搬运字节：此时 CPU 访问 OAM 读到 0xFF、写入被忽略。
78	    pub fn oam_blocked(&self) -> bool {
79	        self.transferring
80	    }
81	}
82	
83	impl Snapshot for Dma {
84	    fn save(&self, w: &mut StateWriter) {
85	        w.tag(b"DMA ");
86	        w.u8(self.reg);
87	        w.u8(self.page);
88	        w.u8(self.index);
89	        w.bool(self.pending.is_some());
90	        w.u8(self.pending.unwrap_or(0));
91	        w.bool(self.transferring);
92	    }
93	
94	    /// 全部读完并校验后才写回；失败时状态不变。
95	    fn load(&mut self, r: &mut StateReader) -> Result<(), StateError> {
96	        r.tag(b"DMA ")?;
97	        let reg = r.u8()?;
98	        let page = r.u8()?;
99	        let index = r.u8()?;
100	        let has_pending = r.bool()?;
101	        let pending_page = r.u8()?;
102	        let transferring = r.bool()?;
103	        if index > DMA_LEN {
104	            return Err(StateError::Corrupt("DMA index"));
105	        }
106	        *self = Dma { reg, page, index, pending: has_pending.then_some(pending_page), transferring };
107	        Ok(())
108	    }
109	}

