/// TAC 低 2 位选择的系统计数器位（T-cycle 计数器中的位掩码）。
const TAC_BIT: [u16; 4] = [1 << 9, 1 << 3, 1 << 5, 1 << 7];

/// 开机（PC=0x0100 时）的系统计数器值：DIV 读出 0xAB（Power_Up_Sequence）。
///
/// 低 8 位（DIV 内部相位）取实机测得的值：从 PC=0x0100 起第 14 个 M-cycle 的访问恰好在 DIV 加 1
